  const payload = typeof notification === 'string'
    ? { text: notification }
    : (notification || {})
  const { text, type } = payload
  const existing = text ? state.notifications?.find(n => n.text === text) : null
  if (existing) {
    existing.ts = moment().format("HH:mm:ss")
