import { v4 as uuidv4 } from 'uuid';
import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'

export const namespaced = true

const EVENT_EXPIRE_SECONDS = 120
setInterval(() => $storex.session.tick(), 1000)

import { API } from '../api/api'
import { publishFileEvent } from '../utils/fileEvents'

// ── HTTP interceptors ────────────────────────────────────────────────────────
API.interceptors = {
  request: [
    (config) => {
      $storex.session.incApiCalls()
      return config
    },
    (error) => {
      $storex.session.decApiCalls()
      return Promise.reject(error)
    }
  ],
  response: [
    (response) => {
      $storex.session.decApiCalls()
      return response
    },
    (error) => {
      $storex.session.decApiCalls()
      $storex.session.setLastError(error)
      console.error("API ERROR:", error)
      $storex.session.onError(error.toString())
    }
  ]
}

export const state = () => ({
  apiCalls: 0,
  lastError: null,
  id: uuidv4(),
  ts: new Date().getTime(),
  notifications: [],
  connected: false,
  user: {
    userName: new Date().getTime()
  },
  users: null,
  events: []
})

export const getters = getterTree(state, {
  lastEvent: state => state.events[state.events.length - 1]?.data,
  wikiEvents: ({ events }) => events.filter(e => e.data?.type === 'wiki'),
  /** Expose the SocketManager so components can call API.socket directly */
  socket: () => API.socket
})

export const mutations = mutationTree(state, {
  incApiCalls(state) {
    state.apiCalls = state.apiCalls + 1
  },
  decApiCalls(state) {
    state.apiCalls = state.apiCalls - 1
  },
  setLastError(state, error) {
    state.lastError = error
  },
  set$childCodxJuior(state, $childCodxJuior) {
    state.$childCodxJuior = $childCodxJuior
  },
  addNotification(_, notification) {
    $storex.ui.addNotification(notification)
  },
  setConnected(state, connected) {
    state.connected = connected
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init () {
      $storex.session.connect()
    },

    tick ({ state }) {
      const expireNotif = new Date( Date.now() - 1000 * EVENT_EXPIRE_SECONDS ).getTime()
      if (state.events.find(e => e.ts < expireNotif)) {
        state.events = state.events.filter(e => e.ts >= expireNotif)
      }
    },

    connect () {
      if (!API.user) {
        API.disconnectSocket()
        return
      }

      API.initSocket({
        onConnect(socketId) {
          console.log('[session] socket connected', socketId)
          // Expose the live socket id on the API connection so REST requests
          // carry the `x-sid` header (used by the meets API to target
          // signaling at this session).
          if (API.connection) API.connection.sid = socketId
          $storex.session.setConnected(true)
          $storex.session.login()
        },
        onDisconnect() {
          console.log('[session] socket disconnected')
          $storex.session.setConnected(false)
        },
        onEvent(payload) {
          $storex.session.onEvent(payload)
        }
      })
    },

    login({ state }) {
      API.socket.emit('codx-junior-login', { user: API.user }, users => {
        state.users = users
      })
    },

    onEvent({ state }, { event, data }) {
      console.log("On server message", event, data)
      state.events.push({ event, data, ts: new Date().getTime() })
      const { codx_path, type, chat } = data
      if (codx_path) {
        data.project = $storex.projects.allProjects?.find(p => p.codx_path === codx_path)
      }

      // ──── FILE EVENTS ──────────────────────────────────────
      // File events are identified by their payload (`file_path` + `type`), not
      // by the socket event name, and are published on the `utils/fileEvents`
      // bus. The project is already attached above, so subscribers can tell
      // whether the change belongs to the project they are displaying.
      publishFileEvent(event, data)

      if (chat) {
        $storex.chats.onChatEvent({ event, data })
      }

      // ──── ORCHESTRATION RUNS (long-running tasks) ──────────
      // Every run transition (run_created, step_started, run_paused,
      // run_completed, ...) carries `run_id` / `status` / `progress`. The
      // orchestration store patches its cached run and debounces a detail
      // refresh; ChatView renders it through `chat.run_id`.
      if (event === 'codx-junior-orchestration') {
        $storex.orchestration.onSocketEvent(data)
      }

      // ──── CHAT TURNS (processing / stalled messages) ───────
      // The server publishes the live state of the project's chat turns:
      // a message whose turn stopped making progress is DEAD (hung request,
      // blocked tool, dead process) and the chat offers a re-run action.
      // This is what replaces polling `/chat/processing`.
      if (event === 'codx-junior-chat-turns') {
        $storex.chats.onChatTurnsEvent(data)
      }
      if (type === 'notification') {
        $storex.ui.addNotification(data)
        // A machine raised a handoff (`needs_user`, emitted for login / MFA /
        // captcha / payment approval): refresh the session list so the rail and
        // the chat icon blink right away. The API stays the single source of
        // truth for the flag — it turns false after take-control.
        if (data?.needs_user) {
          $storex.browsers.loadSessions?.()
        }
      }
      if (event === 'codx-junior-online-users') {
        $storex.users.setOnlineUsers(data.users)
      }

      // ──── MEET EVENTS (WebRTC calls) ───────────────────────
      // Lifecycle delivered as `codx-junior-meet` and WebRTC signalling as
      // `codx-junior-meet-signal` (see the meets API integration guide).
      if (event === 'codx-junior-meet') {
        $storex.meets.handleMeetEvent(data)
      }
      if (event === 'codx-junior-meet-signal') {
        $storex.meets.handleMeetSignal(data)
      }
    },

    onInfo(_, notification) {
      if (typeof notification === 'string') {
